import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"Environment variables","description":"","frontmatter":{},"headers":[],"relativePath":"reference/environment.md","filePath":"reference/environment.md","lastUpdated":1788348125000}`),a={name:`reference/environment.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="environment-variables" tabindex="-1">Environment variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to “Environment variables”">​</a></h1><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>WG_EASY_URL</code></td><td>yes</td><td>—</td><td>Base URL of the wg-easy web UI, e.g. <code>https://vpn.example.com:51821</code></td></tr><tr><td><code>WG_EASY_USERNAME</code></td><td>yes</td><td>—</td><td>Username of a wg-easy admin account (2FA must be disabled)</td></tr><tr><td><code>WG_EASY_PASSWORD</code></td><td>yes</td><td>—</td><td>Password of that account</td></tr><tr><td><code>WG_EASY_INSECURE_TLS</code></td><td>no</td><td><code>false</code></td><td><code>true</code> accepts self-signed certificates, scoped to the wg-easy connection</td></tr><tr><td><code>WG_EASY_READ_ONLY</code></td><td>no</td><td><code>false</code></td><td><code>1</code>/<code>true</code>/<code>yes</code> registers <code>list_clients</code>, <code>get_client</code>, <code>get_server_info</code> only</td></tr><tr><td><code>WG_EASY_ALLOW_TOOLS</code></td><td>no</td><td>—</td><td>Tool names, <code>list_*</code> prefixes or <code>essential</code>; only these register</td></tr><tr><td><code>WG_EASY_DENY_TOOLS</code></td><td>no</td><td>—</td><td>Same syntax; subtracted from whatever the allow list left</td></tr><tr><td><code>ELICITATION</code></td><td>no</td><td><code>true</code></td><td><code>false</code> replaces the approval dialog with the two-call token. <strong>Not prefixed</strong></td></tr></tbody></table><p>There is no configuration file and no command-line flag; these are the whole surface. The reasoning behind each is in <a href="/guide/configuration">Configuration</a>.</p><h2 id="validation-at-startup" tabindex="-1">Validation at startup <a class="header-anchor" href="#validation-at-startup" aria-label="Permalink to “Validation at startup”">​</a></h2><table tabindex="0"><thead><tr><th>Condition</th><th>Result</th></tr></thead><tbody><tr><td>A required variable is missing</td><td>Warning; the server starts and lists tools</td></tr><tr><td><code>WG_EASY_URL</code> does not parse</td><td><strong>Exit 1</strong></td></tr><tr><td><code>WG_EASY_URL</code> scheme is not <code>http</code>/<code>https</code></td><td><strong>Exit 1</strong></td></tr><tr><td><code>WG_EASY_URL</code> contains <code>user:password@</code></td><td><strong>Exit 1</strong></td></tr><tr><td><code>WG_EASY_URL</code> is plain http to a non-loopback host</td><td>Warning about unencrypted credentials and keys</td></tr><tr><td><code>WG_EASY_INSECURE_TLS=true</code></td><td>Warning that certificate validation is relaxed</td></tr><tr><td><code>ELICITATION</code> is neither <code>true</code> nor <code>false</code></td><td><strong>Exit 1</strong>, naming both valid values</td></tr><tr><td><code>ELICITATION=false</code></td><td>One line saying guarded tools fall back to the two-call token</td></tr></tbody></table><p>All diagnostics go to <strong>stderr</strong>, which is where MCP stdio servers must log — stdout carries the protocol.</p><h2 id="elicitation" tabindex="-1"><code>ELICITATION</code> <a class="header-anchor" href="#elicitation" aria-label="Permalink to “ELICITATION”">​</a></h2><p>Whether a client that <em>can</em> show a dialog is asked before <code>create_client</code>, <code>update_client</code>, <code>enable_client</code>, <code>delete_client</code> or <code>generate_one_time_link</code> acts. <code>false</code> takes the two-call-token path instead — it does not remove the guard, and a server started with it off prints one line saying so.</p><p>Two ways it differs from every other variable here:</p><ul><li><strong>No prefix.</strong> One <code>export ELICITATION=false</code> reaches every MCP server in the same environment, not just this one. That is the point of it and also its risk; see <a href="/guide/approval">Asking a person</a>.</li><li><strong>Fatal on anything else.</strong> Where <code>WG_EASY_INSECURE_TLS</code> fails <em>off</em> on a typo, this one stops the server with exit code 1. It is the only variable here that defaults to <em>on</em>, and a typo that fell back would leave the dialog running while you believed it was off.</li></ul><p>Values are trimmed and matched case-insensitively. It is read <em>after</em><code>WG_EASY_USERNAME</code> and <code>WG_EASY_PASSWORD</code> are deleted from <code>process.env</code>, so the fatal path cannot leave the credentials sitting there for a crash reporter.</p><h2 id="wg-easy-read-only" tabindex="-1"><code>WG_EASY_READ_ONLY</code> <a class="header-anchor" href="#wg-easy-read-only" aria-label="Permalink to “WG_EASY_READ_ONLY”">​</a></h2><p>Registers <code>list_clients</code>, <code>get_client</code> and <code>get_server_info</code>, and nothing else.</p><p>Note what it <strong>also</strong> suppresses, because the name does not say it: <code>get_client_config</code> and <code>get_client_qrcode</code>. Both are reads — nothing on the instance changes, and both carry <code>readOnlyHint: true</code> — but what they read is a client&#39;s private key in the clear. Read-only mode is the coarse switch for putting this server in front of a less trusted session, so leaving key disclosure standing would make the mode weaker than its name. <code>list_clients</code> followed by <code>get_client_config</code> yields one ready-to-use VPN configuration per peer.</p><p>They are also out of <code>WG_EASY_ALLOW_TOOLS=essential</code>. To have them, name them: <code>WG_EASY_ALLOW_TOOLS=essential,get_client_config</code> — which is not available under read-only mode, where they are suppressed outright.</p><p>What it does <strong>not</strong> suppress: <code>get_client</code> and <code>list_clients</code> still return every client&#39;s addresses, routes and public key. Private keys, pre-shared keys and live one-time-link tokens are redacted from both.</p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to “Notes”">​</a></h2><ul><li><code>WG_EASY_READ_ONLY</code> accepts <code>1</code>, <code>true</code> and <code>yes</code>, trimmed and case-insensitively. It is the switch that fails <em>towards</em> the restriction, so every spelling an operator plausibly writes has to close it — <code>WG_EASY_READ_ONLY=1</code> silently leaving the write tools registered is the one outcome it must not have.</li><li>Only the exact string <code>true</code> enables <code>WG_EASY_INSECURE_TLS</code>; anything else, including <code>1</code> and <code>yes</code>, leaves it off. The asymmetry with the line above is deliberate: a typo there fails towards relaxed certificate validation, so that one keeps the exact-match rule.</li><li>Trailing slashes on <code>WG_EASY_URL</code> are stripped.</li><li><code>WG_EASY_USERNAME</code> and <code>WG_EASY_PASSWORD</code> are <strong>deleted from <code>process.env</code></strong> once the configuration has been read.</li><li>The wg-easy connection uses a 15-second request timeout and refuses to follow redirects.</li></ul><h2 id="narrowing-the-tool-list" tabindex="-1">Narrowing the tool list <a class="header-anchor" href="#narrowing-the-tool-list" aria-label="Permalink to “Narrowing the tool list”">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>WG_EASY_ALLOW_TOOLS</code></td><td>no</td><td>Tool names, <code>list_*</code> prefixes or <code>essential</code>; only these register</td></tr><tr><td><code>WG_EASY_DENY_TOOLS</code></td><td>no</td><td>Same syntax; subtracted from whatever the allow list left</td></tr></tbody></table><p>Both are comma-separated. Each entry is either an exact tool name or a prefix with a single trailing <code>*</code>. Entries are trimmed and matched case-insensitively; empty entries are ignored, and a value that is empty or only whitespace counts as unset — <code>WG_EASY_ALLOW_TOOLS=</code> in a compose file does not mean &quot;allow nothing&quot;. <code>essential</code> is recognised only in the allow list, and selects <code>get_server_info</code>, <code>list_clients</code>, <code>get_client</code>, <code>create_client</code>, <code>get_client_config</code>, <code>get_client_qrcode</code>, <code>enable_client</code>, <code>disable_client</code>.</p><p><strong>An entry that matches no tool aborts startup</strong>, naming the entry and listing the valid names, as does a malformed pattern such as <code>*_x</code> or <code>list_*_x</code>. The alternative — ignoring the entry — leaves a tool missing from <code>tools/list</code> with nothing pointing at the cause. If both lists together remove everything, the server refuses to start rather than offering an empty tool list.</p><p>Under <code>WG_EASY_READ_ONLY</code>, an exact write-tool name in the allow list is an error naming the read-only setting rather than &quot;unknown tool&quot;; a pattern covering write tools is accepted and merely contributes nothing, with a warning on stderr. Deny entries are exempt: denying an already-suppressed tool is how a defensive list is written.</p>`,23)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};